mapper.select:
select id, user_id, activity_id, activity_name, goods_id, goods_name,
       source, channel, order_id, out_trade_no, original_price,
       seckill_price, status, create_time, update_time
from ${tableName}
where user_id = #{item.userId}
  and out_trade_no = #{item.outTradeNo}
limit 1

select count(1)
from ${tableName}
where activity_id = #{activityId}
  and status in (0, 1)

mapper.update:
update ${tableName}
set status = 2,
    update_time = now()
where order_id = #{orderId}
  and status = 0
